    "id": "orden",
    "titulo": "Orden de publicación",
    "html": "<section class=\"lu-claro\" style=\"background:#FFFFFF;color:#151515;--rosa:#C8661F;--paper:#151515;--muted:#8A8580;--soft:#4A4744;--g1:#F4F1EC;--line:#E7E2DB\"><style>.pm .pm-lienzo .lu-claro .pm-card-r,.pm .pm-lienzo .lu-claro .pill-r{background:#FFC48F}.pm .pm-lienzo .lu-claro .pm-card{box-shadow:0 2px 14px rgba(0,0,0,.04)}</style><p class=\"abs a pm-eyebrow\" style=\"left:128px;top:128px;--d:0\">Calendario · martes, jueves y sábado</p><h2 class=\"abs a disp\" style=\"left:128px;top:176px;width:1664px;font-size:56px;line-height:1.05;--d:1\">Por dónde empezar</h2><div class=\"abs pm-card pop\" style=\"left:128px;top:290px;width:396px;height:560px;--d:0\"></div><p class=\"abs a \" style=\"left:158px;top:320px;width:340px;font-size:26px;line-height:1.4;font-weight:800;--d:1\">Esta semana</p><p class=\"abs a rosa\" style=\"left:158px;top:360px;width:340px;font-size:18px;line-height:1.4;font-weight:700;letter-spacing:.08em;text-transform:uppercase;--d:1\">24-29 nov</p><p class=\"abs a muted\" style=\"left:158px;top:430px;width:340px;font-size:18px;line-height:1.4;font-weight:700;--d:2\">Jue 26</p><p class=\"abs a \" style=\"left:158px;top:458px;width:336px;font-size:22px;line-height:1.4;font-weight:700;line-height:1.25;--d:2\">04 · Sentadilla sin glúteo</p><p class=\"abs a muted\" style=\"left:158px;top:560px;width:340px;font-size:18px;line-height:1.4;font-weight:700;--d:2\">Sáb 28</p><p class=\"abs a \" style=\"left:158px;top:588px;width:336px;font-size:22px;line-height:1.4;font-weight:700;line-height:1.25;--d:2\">17 · Mis 20 minutos (¡MAMIIII!)</p><div class=\"abs pm-card pop\" style=\"left:552px;top:290px;width:396px;height:560px;--d:1\"></div><p class=\"abs a \" style=\"left:582px;top:320px;width:340px;font-size:26px;line-height:1.4;font-weight:800;--d:2\">Semana de Laponia</p><p class=\"abs a rosa\" style=\"left:582px;top:360px;width:340px;font-size:18px;line-height:1.4;font-weight:700;letter-spacing:.08em;text-transform:uppercase;--d:2\">1-6 dic · programada</p><p class=\"abs a muted\" style=\"left:582px;top:430px;width:340px;font-size:18px;line-height:1.4;font-weight:700;--d:3\">Mar 1</p><p class=\"abs a \" style=\"left:582px;top:458px;width:336px;font-size:22px;line-height:1.4;font-weight:700;line-height:1.25;--d:3\">05 · Abdominales sin dolor de cuello</p><p class=\"abs a muted\" style=\"left:582px;top:560px;width:340px;font-size:18px;line-height:1.4;font-weight:700;--d:3\">Jue 3</p><p class=\"abs a \" style=\"left:582px;top:588px;width:336px;font-size:22px;line-height:1.4;font-weight:700;line-height:1.25;--d:3\">12 · Fuerza a partir de los 35</p><p class=\"abs a muted\" style=\"left:582px;top:690px;width:340px;font-size:18px;line-height:1.4;font-weight:700;--d:3\">Sáb 5</p><p class=\"abs a \" style=\"left:582px;top:718px;width:336px;font-size:22px;line-height:1.4;font-weight:700;line-height:1.25;--d:3\">02 · 15 minutos son suficientes</p><div class=\"abs pm-card pop\" style=\"left:976px;top:290px;width:396px;height:560px;--d:2\"></div><p class=\"abs a \" style=\"left:1006px;top:320px;width:340px;font-size:26px;line-height:1.4;font-weight:800;--d:3\">Vuelta</p><p class=\"abs a rosa\" style=\"left:1006px;top:360px;width:340px;font-size:18px;line-height:1.4;font-weight:700;letter-spacing:.08em;text-transform:uppercase;--d:3\">8-13 dic</p><p class=\"abs a muted\" style=\"left:1006px;top:430px;width:340px;font-size:18px;line-height:1.4;font-weight:700;--d:4\">Mar 8</p><p class=\"abs a \" style=\"left:1006px;top:458px;width:336px;font-size:22px;line-height:1.4;font-weight:700;line-height:1.25;--d:4\">06 · Puente sin lumbares</p><p class=\"abs a muted\" style=\"left:1006px;top:560px;width:340px;font-size:18px;line-height:1.4;font-weight:700;--d:4\">Jue 10</p><p class=\"abs a \" style=\"left:1006px;top:588px;width:336px;font-size:22px;line-height:1.4;font-weight:700;line-height:1.25;--d:4\">Laponia · Entrena donde estés</p><p class=\"abs a muted\" style=\"left:1006px;top:690px;width:340px;font-size:18px;line-height:1.4;font-weight:700;--d:4\">Sáb 12</p><p class=\"abs a \" style=\"left:1006px;top:718px;width:336px;font-size:22px;line-height:1.4;font-weight:700;line-height:1.25;--d:4\">08 · Día 1 vs. día 4</p><div class=\"abs pm-card pop\" style=\"left:1400px;top:290px;width:396px;height:560px;--d:3\"></div><p class=\"abs a \" style=\"left:1430px;top:320px;width:340px;font-size:26px;line-height:1.4;font-weight:800;--d:4\">Antes de Navidad</p><p class=\"abs a rosa\" style=\"left:1430px;top:360px;width:340px;font-size:18px;line-height:1.4;font-weight:700;letter-spacing:.08em;text-transform:uppercase;--d:4\">15-20 dic</p><p class=\"abs a muted\" style=\"left:1430px;top:430px;width:340px;font-size:18px;line-height:1.4;font-weight:700;--d:5\">Mar 15</p><p class=\"abs a \" style=\"left:1430px;top:458px;width:336px;font-size:22px;line-height:1.4;font-weight:700;line-height:1.25;--d:5\">09 · Más fuertes, no más pequeñas</p><p class=\"abs a muted\" style=\"left:1430px;top:560px;width:340px;font-size:18px;line-height:1.4;font-weight:700;--d:5\">Jue 17</p><p class=\"abs a \" style=\"left:1430px;top:588px;width:336px;font-size:22px;line-height:1.4;font-weight:700;line-height:1.25;--d:5\">19 · ¿Por qué no una más barata?</p><p class=\"abs a muted\" style=\"left:1430px;top:690px;width:340px;font-size:18px;line-height:1.4;font-weight:700;--d:5\">Sáb 19</p><p class=\"abs a \" style=\"left:1430px;top:718px;width:336px;font-size:22px;line-height:1.4;font-weight:700;line-height:1.25;--d:5\">18 · Mi mayor motivación</p><p class=\"abs a muted\" style=\"left:128px;top:890px;width:1664px;font-size:22px;line-height:1.4;--d:6\">Mezcla siempre enseñanza, humor y conexión en la misma semana. El resto de guiones, a partir de enero.</p><div class=\"foot\" style=\"left:128px;\"><span>Maen Studios × Level Up Workout</span><span class=\"n\">23</span></div></section>"
